import unittest
from candidate import median

class TestMedian(unittest.TestCase):
    def test_median_odd_length_list(self):
        self.assertEqual(median([3, 1, 2, 4, 5]), 3)

    def test_median_even_length_list(self):
        self.assertAlmostEqual(median([-10, 4, 6, 1000, 10, 20]), 15.0)

    def test_median_single_element(self):
        self.assertEqual(median([5]), 5)

    def test_median_duplicate_elements(self):
        self.assertEqual(median([2, 2, 3, 4, 4]), 3)

    def test_median_negative_numbers(self):
        self.assertEqual(median([-5, -2, -1, -3]), -2)

    def test_median_mixed_numbers(self):
        self.assertAlmostEqual(median([-1, 0, 1, 2, 3]), 1)

    def test_median_empty_list(self):
        with self.assertRaises(TypeError):
            median([])

    def test_median_none_input(self):
        with self.assertRaises(TypeError):
            median(None)

    def test_median_non_list_input(self):
        with self.assertRaises(TypeError):
            median("not a list")

    def test_median_list_with_floats(self):
        self.assertAlmostEqual(median([1.5, 2.5, 3.5, 4.5]), 3.0)

    def test_median_list_with_mixed_types(self):
        with self.assertRaises(TypeError):
            median([1, "two", 3])

    def test_median_very_large_numbers(self):
        self.assertAlmostEqual(median([10**18, 2*10**18, 3*10**18]), 2*10**18)

    def test_median_duplicate_median_values(self):
        self.assertEqual(median([1, 2, 2, 3, 3]), 2)

    def test_median_uniquely_sorted_list(self):
        self.assertEqual(median([1, 2, 3, 4, 5]), 3)

    def test_median_reverse_sorted_list(self):
        self.assertEqual(median([5, 4, 3, 2, 1]), 3)
